import importlib.util,unittest
from pathlib import Path
p=str(Path(__file__).with_name('validate_ldd.py'))
s=importlib.util.spec_from_file_location('v',p); v=importlib.util.module_from_spec(s);s.loader.exec_module(v)
class Tests(unittest.TestCase):
 def base(self): return '\n'.join(['level_id: A','document_version: 1','template_version: 0.1','lifecycle_state: draft','source_manifest: S1']+[f'## {i+1}. {h}\nEvidence or explicit unknown.' for i,h in enumerate(v.HEADINGS)])
 def test_valid(self): self.assertEqual(v.validate(self.base())['state'],'pass')
 def test_missing(self): self.assertEqual(v.validate(self.base().replace('## 2. Learning and mechanic boundaries','## Other'))['state'],'fail')
 def test_duplicate(self): self.assertEqual(v.validate(self.base()+'\n## 7. Validation and review handoff\nAgain')['state'],'fail')
 def test_order(self): self.assertEqual(v.validate(self.base().replace('## 1.','## 2.'))['state'],'fail')
 def test_empty(self): self.assertEqual(v.validate(self.base().replace('Evidence or explicit unknown.','',1))['state'],'fail')
 def test_metadata(self): self.assertEqual(v.validate(self.base().replace('level_id: A','level_id: '))['state'],'fail')
 def test_placeholder(self): self.assertEqual(v.validate(self.base()+'\n{{MISSING}}')['state'],'fail')
 def test_fenced(self): self.assertEqual(v.validate('```markdown\n'+self.base()+'\n```')['state'],'fail')
 def test_tilde_fenced(self): self.assertEqual(v.validate('~~~~\n'+self.base()+'\n~~~~')['state'],'fail')
 def test_fenced_duplicate_ignored(self): self.assertEqual(v.validate(self.base()+'\n```\n## 1. Level design brief\n```')['state'],'pass')
 def test_bad_state(self): self.assertEqual(v.validate(self.base().replace('lifecycle_state: draft','lifecycle_state: done'))['state'],'fail')
 def test_unproven_ready(self): self.assertEqual(v.validate(self.base().replace('lifecycle_state: draft','lifecycle_state: implementation_ready'))['state'],'fail')
 def test_pending_evidence(self): self.assertEqual(v.validate(self.base().replace('lifecycle_state: draft','lifecycle_state: human_accepted')+'\nhuman_acceptance_evidence: pending')['state'],'fail')
 def test_declared_evidence(self): self.assertEqual(v.validate(self.base().replace('lifecycle_state: draft','lifecycle_state: independently_reviewed')+'\nindependent_review_evidence: review-record-1')['state'],'pass')
 def test_invalid_backtick_closer(self): self.assertEqual(v.validate('```markdown\n```not-a-closer\n'+self.base())['state'],'fail')
 def test_invalid_tilde_closer(self): self.assertEqual(v.validate('~~~markdown\n~~~not-a-closer\n'+self.base())['state'],'fail')
 def test_empty_promotion(self): self.assertEqual(v.validate(self.base().replace('lifecycle_state: draft','lifecycle_state: human_accepted')+'\nhuman_acceptance_evidence:   ')['state'],'fail')
 def test_scope(self): self.assertIn('playability',v.validate(self.base())['not_verified'])
if __name__=='__main__':unittest.main()
